import static org.junit.Assert.*;

public class DateTimeFormatter_parseInto_TriageGen0Test {

    /**
     * Tests that passing a null instant throws IllegalArgumentException.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testParseInto_NullInstant_ThrowsException() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder().appendInstantPattern("yyyy-MM-dd").toFormatter();
        formatter.parseInto(null, "2023-01-01", 0);
    }

    /**
     * Tests standard parsing where the text matches the pattern and updates the instant.
     * Covers the basic line execution path.
     */
    @Test
    public void testParseInto_StandardParsing() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral('-')
                .appendMonthOfYear()
                .appendLiteral('-')
                .appendDayOfMonth()
                .toFormatter();

        // Using a Mock/Real implementation of ReadWritableInstant via MutableDateTime or similar logic
        // Since ReadWritableInstant is an interface, we use a concrete implementation provided by Joda
        // In Joda, MutableDateTime implements ReadWritableInstant.
        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2000, 1, 1, 0, 0);

        String text = "2023-10-25";
        int position = 0;

        int newPos = formatter.parseInto(instant, text, position);

        Assert.assertEquals(10, newPos);
        Assert.assertEquals(2023, instant.getYear());
        Assert.assertEquals(10, instant.getMonthOfYear());
        Assert.assertEquals(25, instant.getDayOfMonth());
    }

    /**
     * Tests the branch where iOffsetParsed is true and an offset is present in the text.
     * This covers the 'if (iOffsetParsed && bucket.getOffsetInteger() != null)' branch.
     */
    @Test
    public void testParseInto_WithOffsetParsed() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral('-')
                .appendMonthOfYear()
                .appendLiteral('-')
                .appendDayOfMonth()
                .appendLiteral(' ')
                .appendHourOfDay()
                .appendLiteral(':')
                .appendMinuteOfHour()
                .appendLiteral(' ')
                .appendOffset("+HH:mm")
                .toFormatter()
                .withOffsetParsed();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2000, 1, 1, 0, 0);
        String text = "2023-10-25 14:30 +05:00";

        formatter.parseInto(instant, text, 0);

        // The instant should be updated to the parsed time. 
        // Note: instant.setMillis is called with the computed millis from the bucket.
        Assert.assertEquals(2023, instant.getYear());
        Assert.assertEquals(14, instant.getHourOfDay());
        Assert.assertEquals(30, instant.getMinuteOfHour());
        // Check if zone was updated via the parsed offset
        Assert.assertEquals(DateTimeZone.forOffsetHours(5), instant.getZone());
    }

    /**
     * Tests the branch where iOffsetParsed is false but the bucket contains a zone.
     * This covers the 'else if (bucket.getZone() != null)' branch.
     */
    @Test
    public void testParseInto_WithZoneInBucket() {
        // Creating a pattern that doesn't explicitly parse offset but might imply a zone if the parser handles it
        // Or more simply, a formatter that has a fixed zone set via withZone.
        DateTimeZone targetZone = DateTimeZone.forID("America/New_York");
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral('-')
                .appendMonthOfYear()
                .appendLiteral('-')
                .appendDayOfMonth()
                .toFormatter()
                .withZone(targetZone);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2000, 1, 1, 0, 0);
        String text = "2023-10-25";

        formatter.parseInto(instant, text, 0);

        Assert.assertEquals(targetZone, instant.getZone());
    }

    /**
     * Tests the branch where iZone is not null.
     * This covers the 'if (iZone != null)' branch.
     */
    @Test
    public void testParseInto_WithFixedZone() {
        DateTimeZone fixedZone = DateTimeZone.UTC;
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral('-')
                .appendMonthOfYear()
                .appendLiteral('-')
                .appendDayOfMonth()
                .toFormatter()
                .withZone(fixedZone);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2000, 1, 1, 0, 0);
        String text = "2023-10-25";

        formatter.parseInto(instant, text, 0);

        Assert.assertEquals(fixedZone, instant.getZone());
    }

    /**
     * Tests the behavior with different Locales to ensure iLocale is utilized.
     */
    @Test
    public void testParseInto_WithLocale() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendMonthOfYear(java.time.format.TextStyle.FULL)
                .appendDayOfMonth()
                .toFormatter()
                .withLocale(Locale.FRENCH);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2000, 1, 1, 0, 0);
        // "octobre" is French for October
        String text = "octobre 25";

        formatter.parseInto(instant, text, 0);

        Assert.assertEquals(10, instant.getMonthOfYear());
        Assert.assertEquals(25, instant.getDayOfMonth());
    }
}
